WITH alvos AS (SELECT * FROM UNNEST(['PA-1506187-94551B72659E427F961D2F62CEBA7392','PA-1506187-CEAD1A3AC3E14F5DB2FC0B93E54E7E98','MS-5006606-4693892971CF47B4B2684C3A94950BEE','BA-2921401-9177991E4861442EACFE3ACDDC06DB91','BA-2929057-C5D11EE026A64399A6EF36764E8739E9']) AS id_imovel),a AS (SELECT * FROM `basedosdados.br_sfb_sicar.area_imovel` WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY id_imovel ORDER BY data_extracao DESC)=1),pares AS (SELECT t.id_imovel alvo_id,v.* FROM a t JOIN alvos USING(id_imovel) JOIN a v ON v.id_municipio=t.id_municipio AND v.id_imovel!=t.id_imovel WHERE ST_INTERSECTS(t.geometria,v.geometria)) SELECT alvo_id,v.id_imovel,v.id_municipio,v.sigla_uf,v.area,v.status,v.condicao,v.tipo,v.modulos_fiscais,v.data_criacao,v.data_atualizacao,v.data_extracao FROM pares v ORDER BY alvo_id,v.id_imovel